  constructor(id = '"'') { this.id = id; this.value = ''; this.textContent = ''; this.hidden = false; this.style = {}; this.dataset = {}; this.listeners = {}; this.width = 0; this.height = 0; this.classList = { add(){}, remove(){}, toggle(){} }; }
