function randomPoint(rng, radius, minRadius = 0) {
  const angle = rng() * Math.PI * 2;
  const distance = Math.sqrt(rng()) * (radius - minRadius) + minRadius;
  return { x: Math.cos(angle) * distance, y: Math.sin(angle) * distance };
}

